'use strict';
const $=id=>document.getElementById(id), canvas=$('network'), ctx=canvas.getContext('2d');
let nodes=[],edges=[],nextId=1,selected=null,source=null,tool='select',paused=false;
let states=[],cursor=-1,drag=null,w=600,h=680,accumulator=0,last=0,fpsTime=0,frames=0;
const params={spring:2,repulsion:12000,damping:2};
const clone=v=>JSON.parse(JSON.stringify(v));
function node(id){return nodes.find(n=>n.id===id);}
function snapshot(operation){states.splice(cursor+1);states.push({nodes:clone(nodes),edges:clone(edges),nextId,operation});if(states.length>100)states.shift();cursor=states.length-1;refresh();}
function restore(i){if(i<0||i>=states.length)return;cursor=i;const s=states[i];nodes=clone(s.nodes);edges=clone(s.edges);nextId=s.nextId;selected=source=null;drag=null;accumulator=0;refresh();message(`Estado restaurado: ${s.operation}.`);}
function metrics(){const seen=new Set();let components=0;const adj=new Map(nodes.map(n=>[n.id,[]]));for(const e of edges){adj.get(e.a).push(e.b);adj.get(e.b).push(e.a);}for(const n of nodes){if(seen.has(n.id))continue;components++;const stack=[n.id];seen.add(n.id);while(stack.length){for(const id of adj.get(stack.pop())){if(!seen.has(id)){seen.add(id);stack.push(id);}}}}return {v:nodes.length,e:edges.length,c:components,b:edges.length-nodes.length+components,chi:nodes.length-edges.length};}
function refresh(){const m=metrics();$('vertices').textContent=m.v;$('edges').textContent=m.e;$('beta0').textContent=m.c;$('beta1').textContent=m.b;$('euler').textContent=m.chi;$('degree').textContent=m.v?(2*m.e/m.v).toFixed(2):'0.00';$('identity').textContent=`χ = β₀ − β₁ = ${m.c} − ${m.b} = ${m.chi} ✓`;$('history').textContent=`${cursor+1} / ${states.length}`;$('undo').disabled=cursor<=0;$('redo').disabled=cursor>=states.length-1;$('operation').textContent=states[cursor]?.operation||'Red vacía';const n=node(selected);$('pin').disabled=!n;$('selection').textContent=n?`ID ${n.id} · grado ${edges.filter(e=>e.a===n.id||e.b===n.id).length}\nMasa ${n.mass} · ${n.pinned?'Fijo':'Libre'}`:'Haz clic en un nodo de la red.';$('pin').textContent=n?.pinned?'Liberar vértice':'Fijar vértice';}
function add(x,y){const n={id:nextId++,x,y,vx:0,vy:0,mass:1,pinned:false};nodes.push(n);return n.id;}
function connect(a,b){if(a===b||!node(a)||!node(b)||edges.some(e=>(e.a===a&&e.b===b)||(e.a===b&&e.b===a)))return false;edges.push({a,b,spin:.5,length:90});return true;}
function preset(){nodes=[];edges=[];nextId=1;selected=source=null;drag=null;accumulator=0;const kind=$('preset').value;
if(kind==='lattice'){for(let row=0;row<4;row++)for(let col=0;col<5;col++)add((col-2)*80+(row%2)*40,(row-1.5)*70);for(let i=0;i<nodes.length;i++)for(let j=i+1;j<nodes.length;j++)if(Math.hypot(nodes[i].x-nodes[j].x,nodes[i].y-nodes[j].y)<95)connect(nodes[i].id,nodes[j].id);}
if(kind==='ring'){for(let i=0;i<12;i++)add(Math.cos(i*Math.PI/6)*170,Math.sin(i*Math.PI/6)*170);for(let i=0;i<12;i++)connect(nodes[i].id,nodes[(i+1)%12].id);}
if(kind==='tetra'){add(0,-130);add(-130,90);add(130,90);add(0,0);for(let i=1;i<=4;i++)for(let j=i+1;j<=4;j++)connect(i,j);}
if(kind==='separate'){for(let group=0;group<2;group++){const ids=[];for(let i=0;i<5;i++)ids.push(add((group-.5)*260+Math.cos(i*Math.PI*2/5)*80,Math.sin(i*Math.PI*2/5)*80));for(let i=0;i<5;i++)connect(ids[i],ids[(i+1)%5]);}}
snapshot(`Configuración: ${$('preset').selectedOptions[0].textContent}`);message('Red cargada. Explora sus componentes y ciclos.');}
function message(text){$('message').textContent=text;}
function forces(){const f=nodes.map(()=>({x:0,y:0}));const indices=new Map(nodes.map((n,i)=>[n.id,i]));for(let i=0;i<nodes.length;i++)for(let j=i+1;j<nodes.length;j++){let dx=nodes[i].x-nodes[j].x,dy=nodes[i].y-nodes[j].y;let r=Math.hypot(dx,dy);if(r<1e-8){dx=.001;dy=0;r=.001;}const scale=params.repulsion/((r*r+25)*(r+5));const fx=scale*dx,fy=scale*dy;f[i].x+=fx;f[i].y+=fy;f[j].x-=fx;f[j].y-=fy;}
for(const e of edges){const i=indices.get(e.a),j=indices.get(e.b),a=nodes[i],b=nodes[j];const dx=a.x-b.x,dy=a.y-b.y,r=Math.hypot(dx,dy);if(r<1e-8)continue;const scale=-params.spring*(r-e.length)/r;f[i].x+=scale*dx;f[i].y+=scale*dy;f[j].x-=scale*dx;f[j].y-=scale*dy;}return f;}
function step(dt){const f=forces(),decay=Math.exp(-params.damping*dt/2);nodes.forEach((n,i)=>{if(n.pinned||drag?.id===n.id){n.vx=n.vy=0;return;}n.vx=n.vx*decay+dt*f[i].x/(2*n.mass);n.vy=n.vy*decay+dt*f[i].y/(2*n.mass);n.x+=n.vx*dt;n.y+=n.vy*dt;});const next=forces();nodes.forEach((n,i)=>{if(n.pinned||drag?.id===n.id)return;n.vx=(n.vx+dt*next[i].x/(2*n.mass))*decay;n.vy=(n.vy+dt*next[i].y/(2*n.mass))*decay;});}
function scale(){return Math.min(1,Math.max(.3,(w-50)/480),Math.max(.3,(h-160)/440));}
function draw(){ctx.clearRect(0,0,w,h);ctx.save();ctx.translate(w/2,h/2);ctx.scale(scale(),scale());const map=new Map(nodes.map(n=>[n.id,n]));for(const e of edges){const a=map.get(e.a),b=map.get(e.b);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);const highlighted=e.a===selected||e.b===selected;ctx.strokeStyle=highlighted?'#c4f57e99':'#68818c80';ctx.lineWidth=highlighted?1.8:1;ctx.stroke();if(nodes.length<=30){ctx.fillStyle='#8b9da8';ctx.font='9px monospace';ctx.textAlign='center';ctx.fillText('½',(a.x+b.x)/2,(a.y+b.y)/2-5);}}for(const n of nodes){const active=n.id===selected||n.id===source;ctx.beginPath();ctx.arc(n.x,n.y,active?19:15,0,Math.PI*2);ctx.fillStyle=active?'#c4f57e18':'#c4f57e09';ctx.fill();ctx.beginPath();ctx.arc(n.x,n.y,active?9:7,0,Math.PI*2);ctx.fillStyle=n.pinned?'#6bbaf7':'#c4f57e';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=12;ctx.fill();ctx.shadowBlur=0;if(active){ctx.strokeStyle='#e6ffd3';ctx.lineWidth=1;ctx.beginPath();ctx.arc(n.x,n.y,14,0,Math.PI*2);ctx.stroke();}ctx.fillStyle='#b2c4ce';ctx.font='10px monospace';ctx.textAlign='center';ctx.fillText(n.id,n.x,n.y+27);}ctx.restore();}
function position(e){const rect=canvas.getBoundingClientRect();return {x:(e.clientX-rect.left-w/2)/scale(),y:(e.clientY-rect.top-h/2)/scale()};}
function hit(p){let best=null,dist=22/scale();for(const n of nodes){const d=Math.hypot(p.x-n.x,p.y-n.y);if(d<dist){best=n;dist=d;}}return best;}
function edgeHit(p){let found=null,best=9/scale();for(const e of edges){const a=node(e.a),b=node(e.b),dx=b.x-a.x,dy=b.y-a.y;const t=Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy||1)));const d=Math.hypot(p.x-a.x-t*dx,p.y-a.y-t*dy);if(d<best){found=e;best=d;}}return found;}
canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;const p=position(e),n=hit(p);if(tool==='add'){if(nodes.length>=200){message('Límite de la demo: 200 vértices.');return;}selected=add(p.x,p.y);snapshot(`Agregar vértice ${selected}`);}else if(tool==='edge'){if(!n)return;if(source===null){source=n.id;message(`Origen ${source}. Selecciona otro vértice.`);}else{if(connect(source,n.id)){snapshot(`Conectar ${source} ↔ ${n.id}`);message('Arista agregada.');}else message('Conexión rechazada: evita lazos y aristas duplicadas.');source=null;}}else if(tool==='delete'){if(n){nodes=nodes.filter(v=>v.id!==n.id);edges=edges.filter(edge=>edge.a!==n.id&&edge.b!==n.id);if(selected===n.id)selected=null;source=null;snapshot(`Eliminar vértice ${n.id}`);}else{const edge=edgeHit(p);if(edge){edges.splice(edges.indexOf(edge),1);snapshot(`Eliminar arista ${edge.a} ↔ ${edge.b}`);}}}else{selected=n?.id??null;if(n){drag={id:n.id,offsetX:n.x-p.x,offsetY:n.y-p.y};n.vx=n.vy=0;canvas.setPointerCapture(e.pointerId);}refresh();}});
canvas.addEventListener('pointermove',e=>{if(!drag)return;const n=node(drag.id);if(!n)return;const p=position(e);n.x=p.x+drag.offsetX;n.y=p.y+drag.offsetY;n.vx=n.vy=0;});
const endDrag=()=>{drag=null;};canvas.addEventListener('pointerup',endDrag);canvas.addEventListener('pointercancel',endDrag);canvas.addEventListener('lostpointercapture',endDrag);
for(const button of document.querySelectorAll('[data-tool]'))button.addEventListener('click',()=>{tool=button.dataset.tool;source=null;for(const b of document.querySelectorAll('[data-tool]'))b.classList.toggle('active',b===button);$('hint').textContent={select:'Arrastra un vértice para moverlo. Haz clic para seleccionarlo.',add:'Haz clic en el lienzo para agregar un vértice.',edge:'Haz clic en el origen y después en el destino.',delete:'Haz clic en un vértice o en una arista para eliminarlo.'}[tool];canvas.style.cursor=tool==='select'?'grab':'crosshair';});
$('reset').onclick=preset;$('undo').onclick=()=>restore(cursor-1);$('redo').onclick=()=>restore(cursor+1);
$('pause').onclick=()=>{paused=!paused;accumulator=0;$('pause').textContent=paused?'▶ Reanudar simulación':'Ⅱ Pausar simulación';$('run-status').textContent=paused?'SIMULACIÓN PAUSADA':'SIMULACIÓN ACTIVA';};
$('pin').onclick=()=>{const n=node(selected);if(!n)return;n.pinned=!n.pinned;n.vx=n.vy=0;refresh();message(`Vértice ${n.id} ${n.pinned?'fijado':'liberado'}.`);};
$('fit').onclick=()=>{if(!nodes.length)return;const cx=nodes.reduce((s,n)=>s+n.x,0)/nodes.length,cy=nodes.reduce((s,n)=>s+n.y,0)/nodes.length;const extent=Math.max(1,...nodes.map(n=>Math.max(Math.abs(n.x-cx)/200,Math.abs(n.y-cy)/200)));for(const n of nodes){n.x=(n.x-cx)/extent;n.y=(n.y-cy)/extent;n.vx=n.vy=0;}message('Red centrada.');};
for(const key of ['spring','repulsion','damping'])$(key).addEventListener('input',()=>{params[key]=Number($(key).value);$(key+'-val').textContent=key==='repulsion'?params[key]:params[key].toFixed(1);});
function resize(){const rect=canvas.getBoundingClientRect(),ratio=window.devicePixelRatio||1;w=rect.width;h=rect.height;canvas.width=Math.round(w*ratio);canvas.height=Math.round(h*ratio);ctx.setTransform(ratio,0,0,ratio,0,0);}
new ResizeObserver(resize).observe(canvas);
function frame(time){const elapsed=last?Math.min((time-last)/1000,.1):0;last=time;if(!paused){accumulator+=elapsed;let count=0;while(accumulator>=1/120&&count++<12){step(1/120);accumulator-=1/120;}}draw();frames++;if(time-fpsTime>=1000){$('fps').textContent=Math.round(frames*1000/(time-fpsTime))+' FPS';fpsTime=time;frames=0;}requestAnimationFrame(frame);}
preset();resize();requestAnimationFrame(frame);
